@@ -0,0 +1,36 @@
+import assert from 'node:assert/strict';
+import { readFileSync } from 'node:fs';
+const read=p=>JSON.parse(readFileSync(p,'utf8'));
+const x=read('docs/p9.0.7.2.2-primary-archive-coverage.json');
+const prior=read('docs/p9.0.7.2.1-cross-register-ledger.json');
+const policy=read('docs/p9.0.4.3-promotion-policy.json');
+assert.equal(x.scope_count,85);
+assert.equal(x.rows.length,85);
+assert.equal(new Set(x.rows.map(r=>r.actual_id)).size,85);
+assert.deepEqual(x.rows.map(r=>r.actual_id).sort(),prior.rows.map(r=>r.actual_id).sort());
+assert.equal(x.acts.length,7);
+assert.equal(x.supplemental_local_government_act_leads.length,5);
+assert.equal(x.further_amendment_candidates.length,3);
+assert(x.supplemental_local_government_act_leads.some(a=>a.id==='PMR-2025-97-ZI-VII'));
+assert(x.supplemental_local_government_act_leads.some(a=>a.id==='PMR-2025-223-ZI-VII'));
+assert(x.supplemental_local_government_act_leads.every(a=>a.individual_jurisdiction_change_certified===false));
+assert.equal(new Set(x.acts.map(a=>a.id)).size,7);
+const newAct=x.acts.find(a=>a.id==='PMR-2023-292-ZI-VII');
+assert.equal(newAct.official_publication_id,'2023001593');
+assert.equal(newAct.primary_original_text_verified,false);
+assert.equal(newAct.identity_specific_impact_certified,false);
+assert.equal(x.acts.find(a=>a.id==='PMR-2023-291-ZI-VII').official_publication_id,'2023001591');
+assert.equal(x.acts.find(a=>a.id==='PMR-2024-47-ZI-VII').official_publication_id,'2024000426');
+assert.equal(x.acts.find(a=>a.id==='PMR-2024-48-ZI-VII').official_publication_id,'2024000427');
+assert.equal(x.source_2002_law.sha256,'cca7a2ce713770b841d45643ba616b7bbdfe4a19bac49a152f560a5de116225f');
+assert.equal(x.source_2002_law.archived_in_repo,false);
+assert.deepEqual(x.yearly_completeness.map(y=>y.year),[2023,2024,2025,2026]);
+assert(x.yearly_completeness.every(y=>!y.official_gazette_complete&&!y.all_acts_identified&&!y.primary_pdf_sha256_complete&&!y.all_effective_dates_verified&&!y.all_85_impact_verified));
+assert(x.rows.every(r=>r.legal_md_parent_preserved && !r.satellite_city_amendments_checked_for_name_and_parent&&!r.certified_2023_2026_administrative_parent&&!r.certified_full_polygon_control&&r.semantic_acceptance==='BLOCKED_INCOMPLETE'&&r.p91_import_allowed===false));
+assert.equal(x.certified_individual_parent_changes,0);
+assert.equal(x.complete_normative_chain,false);
+assert.equal(x.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(x.p91_import_allowed,false);
+assert.equal(policy.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(policy.p91_import_allowed,false);
+console.log('P90722_PRIMARY_ARCHIVE_FAIL_CLOSED_PASS: 7 official law entries, 85 identities, 4 incomplete yearly inventories, P9.1 DENIED');
